import { describe, expect, it } from "vitest";
import { clipId, slugify } from "../src/renderer.js";

const TITLE =
  "The Infinity Machine: Demis Hassabis, DeepMind, and the Quest for Superintelligence";

// Golden IDs generated by the retired Python sync.py against the real vault.
describe("clipId", () => {
  it("matches sync.py for a highlight", async () => {
    const id = await clipId({
      title: TITLE,
      type: "highlight",
      location: "496",
      text: "The idea that the gooey mass inside the skull contained some ineffable, unprogrammable something—consciousness? spirit?—was nothing more than biochauvinism.",
    });
    expect(id).toBe("75721b4f3aa3");
  });

  it("matches sync.py for a highlight with curly quotes", async () => {
    const id = await clipId({
      title: TITLE,
      type: "highlight",
      location: "1220",
      text: "“Intelligence measures an agent’s ability to achieve goals in a wide range of environments.”",
    });
    expect(id).toBe("7a5ab33ebd1b");
  });

  it("matches sync.py for a note", async () => {
    const id = await clipId({
      title: TITLE,
      type: "note",
      location: "3557",
      text: "Will AI create new paradigms that we cannot even understand? Think government, education, healthcare",
    });
    expect(id).toBe("ecea02091ab7");
  });

  it("renders a missing location as the string None, like Python", async () => {
    const a = await clipId({ title: "T", type: "highlight", location: null, text: "x" });
    const b = await clipId({ title: "T", type: "highlight", location: "None", text: "x" });
    expect(a).toBe(b);
  });
});

describe("slugify", () => {
  it("matches sync.py slugs", () => {
    expect(slugify(TITLE)).toBe(
      "the-infinity-machine-demis-hassabis-deepmind-and-the-quest-for-superintelligence"
    );
  });
  it("collapses punctuation runs and trims", () => {
    expect(slugify("  Peak: Secrets!! ")).toBe("peak-secrets");
  });
  it("falls back to untitled", () => {
    expect(slugify("!!!")).toBe("untitled");
  });
});
